 function readEducation(){return [...educationRows.querySelectorAll('[data-education]')].map(row=>({qualification:row.querySelector('[data-edu=qualification]').value.trim(),institution:row.querySelector('[data-edu=institution]').value.trim(),start_date:row.querySelector('[data-edu=start_date]').value.trim(),end_date:row.querySelector('[data-edu=end_date]').value.trim()}));}
